/* Test environment for CCSDSSDLSEncryptor.
 *
 * On its first activation the cyclic interface run_tests drives the
 * encryptor through configure_sa / remove_sa / apply_security /
 * process_security and records the outcome of every test in
 * test_results[] and the counters below.
 *
 * AES-256 and AES-CMAC-256 are served by the aes256_mock and cmac256_mock
 * functions, which are deterministic stand-ins, not the real algorithms.
 *
 */
#include "test_env.h"

#include <stdint.h>
#include <string.h>

/* ---------------------------------------------------------------------- */
/* Results, to be read with the debugger                                  */
/* ---------------------------------------------------------------------- */

typedef struct {
   unsigned checks;                 /* checks run */
   unsigned failures;               /* checks failed */
   int line;                        /* line of the first failed check, 0: passed */
   const char *failure;             /* its condition or call */
   asn1SccSDLS_Status got;          /* status returned, when it was a status check */
   asn1SccSDLS_Status expected;     /* status expected, when it was a status check */
} test_result_t;

static volatile test_result_t *g_result;   /* result of the running test */

static void record(int ok, const char *what, int line,
                   asn1SccSDLS_Status got, asn1SccSDLS_Status expected)
{
   g_result->checks++;
   if (ok) {
      return;
   }
   g_result->failures++;
   if (g_result->line == 0) {
      g_result->line = line;
      g_result->failure = what;
      g_result->got = got;
      g_result->expected = expected;
   }
}

#define CHECK(cond) \
   record((cond), #cond, __LINE__, SDLS_Status_ok, SDLS_Status_ok)
#define CHECK_STATUS(call, exp) do { \
      const asn1SccSDLS_Status got_ = (call); \
      record(got_ == SDLS_Status_##exp, #call, __LINE__, got_, SDLS_Status_##exp); \
   } while (0)

