typedef asn1SccSDLS_Protected_Data frame_t;

/* Interface parameters are static: several kilobytes each. */
static asn1SccSDLS_SA_Config g_cfg;
static asn1SccSDLS_Apply_Request g_apply_req;
static asn1SccSDLS_Apply_Response g_apply_resp;
static asn1SccSDLS_Process_Request g_proc_req;
static asn1SccSDLS_Process_Response g_proc_resp;

/* Transfer frame header used by apply() and process(); tests may change
 * it, run_tests restores it before each test. */
static const uint8_t k_default_header[] = { 0x20, 0x03, 0x00, 0x2A, 0x00 };
static uint8_t g_hdr[256];
static size_t g_hdr_len;

/* Plaintext: data(n) is the first n octets of this pattern. */
static uint8_t g_data[2048];

/* Octets of the Security Header (SPI + IV + sequence number + pad length)
 * for the field lengths currently in g_cfg. */
#define SEC_HDR(iv, seq, pad) (2 + (iv) + (seq) + (pad))

static void reset_header(void)
{
   memset(g_hdr, 0, sizeof(g_hdr));
   memcpy(g_hdr, k_default_header, sizeof(k_default_header));
   g_hdr_len = sizeof(k_default_header);
}

/* Fills g_cfg; the key is derived from the SPI so every SA has its own. */
static void sa_config(asn1SccSDLS_SPI spi, asn1SccSDLS_Mode mode,
                      asn1SccSDLS_Auth_Algorithm alg,
                      int iv, int seq, int pad, int mac, unsigned window)
{
   memset(&g_cfg, 0, sizeof(g_cfg));
   g_cfg.spi = spi;
   g_cfg.mode = mode;
   g_cfg.auth_algorithm = alg;
   for (unsigned i = 0; i < sizeof(g_cfg.key.arr); i++) {
      g_cfg.key.arr[i] = (uint8_t)(spi * 31u + i);
   }
   g_cfg.field_lengths.iv = iv;
   g_cfg.field_lengths.seq_num = seq;
   g_cfg.field_lengths.pad_len = pad;
   g_cfg.field_lengths.mac = mac;
   g_cfg.seq_window = window;
}

/* The baseline SA of each service, with anti-replay enabled. */
static void ae_config(asn1SccSDLS_SPI spi)   { sa_config(spi, SDLS_Mode_authenticated_encryption, SDLS_Auth_Algorithm_gmac, 12, 0, 0, 16, 64); }
static void gmac_config(asn1SccSDLS_SPI spi) { sa_config(spi, SDLS_Mode_authentication, SDLS_Auth_Algorithm_gmac, 12, 0, 0, 12, 64); }
static void cmac_config(asn1SccSDLS_SPI spi) { sa_config(spi, SDLS_Mode_authentication, SDLS_Auth_Algorithm_cmac, 0, 4, 0, 8, 64); }
static void enc_config(asn1SccSDLS_SPI spi)  { sa_config(spi, SDLS_Mode_encryption, SDLS_Auth_Algorithm_gmac, 12, 0, 0, 0, 64); }

static asn1SccSDLS_Status configure(void)
{
   asn1SccSDLS_Status st;
   test_env_RI_configure_sa(&g_cfg, &st);
   return st;
}

static asn1SccSDLS_Status remove_sa(asn1SccSDLS_SPI spi)
{
   asn1SccSDLS_Status st;
   test_env_RI_remove_sa(&spi, &st);
   return st;
}

/* Protects the first len octets of g_data under g_hdr; the protected data
 * is copied to out (when not NULL). */
static asn1SccSDLS_Status apply(asn1SccSDLS_SPI spi, size_t len, frame_t *out)
{
   g_apply_req.spi = spi;
   memcpy(g_apply_req.frame_header.arr, g_hdr, g_hdr_len);
   g_apply_req.frame_header.nCount = (int)g_hdr_len;
   memcpy(g_apply_req.data.arr, g_data, len);
   g_apply_req.data.nCount = (int)len;
   test_env_RI_apply_security(&g_apply_req, &g_apply_resp);
   if (out != NULL) {
      *out = g_apply_resp.protected_data;
   }
   return g_apply_resp.status;
}

/* Verifies f under g_hdr; the result is left in g_proc_resp. */
static asn1SccSDLS_Status process(const frame_t *f, const asn1SccSDLS_Channel_Id *rx)
{
   memcpy(g_proc_req.frame_header.arr, g_hdr, g_hdr_len);
   g_proc_req.frame_header.nCount = (int)g_hdr_len;
   g_proc_req.protected_data = *f;
   g_proc_req.exist.rx_channel = (rx != NULL);
   if (rx != NULL) {
      g_proc_req.rx_channel = *rx;
   }
   test_env_RI_process_security(&g_proc_req, &g_proc_resp);
   return g_proc_resp.status;
}

static void set_aes_status(asn1SccCrypto_Status st)  { test_env_RI_set_aes_status(&st); }
static void set_cmac_status(asn1SccCrypto_Status st) { test_env_RI_set_cmac_status(&st); }

/* process() returned exactly the first len octets of g_data. */
static int got_data(size_t len)
{
   return g_proc_resp.data.nCount == (int)len
          && (len == 0 || memcmp(g_proc_resp.data.arr, g_data, len) == 0);
}

/* The 12-octet IV of a GCM frame equals the small integer v. */
static int iv_is(const frame_t *f, unsigned v)
{
   for (int i = 2; i < 12; i++) {
      if (f->arr[i] != 0) {
         return 0;
      }
   }
   return f->arr[12] == (uint8_t)(v >> 8) && f->arr[13] == (uint8_t)v;
}

static asn1SccSDLS_Channel_Id channel(unsigned vcid, int map_id)
{
   asn1SccSDLS_Channel_Id ch;
   memset(&ch, 0, sizeof(ch));
   ch.tfvn = 0;
   ch.scid = 0x2A;
   ch.vcid = vcid;
   ch.exist.map_id = (map_id >= 0);
   ch.map_id = (map_id >= 0) ? (asn1SccUint)map_id : 0;
   return ch;
}

