static frame_t f1, f2, f3, f4, t;

static void test_authenticated_encryption(void)
{
   ae_config(1);
   CHECK_STATUS(configure(), ok);

   CHECK_STATUS(apply(1, 64, &f1), ok);
   CHECK(f1.nCount == SEC_HDR(12, 0, 0) + 64 + 16);
   CHECK(f1.arr[0] == 0x00 && f1.arr[1] == 0x01);           /* SPI */
   CHECK(iv_is(&f1, 1));                                    /* first IV is 1 */
   CHECK(memcmp(f1.arr + 14, g_data, 64) != 0);             /* encrypted */

   CHECK_STATUS(process(&f1, NULL), ok);
   CHECK(g_proc_resp.spi == 1);
   CHECK(got_data(64));

   /* The IV advances, so the same plaintext encrypts differently. */
   CHECK_STATUS(apply(1, 64, &f2), ok);
   CHECK(iv_is(&f2, 2));
   CHECK(memcmp(f1.arr + 14, f2.arr + 14, 64) != 0);
   CHECK_STATUS(process(&f2, NULL), ok);
   CHECK(got_data(64));
}

static void test_authentication_gmac(void)
{
   gmac_config(2);
   CHECK_STATUS(configure(), ok);

   CHECK_STATUS(apply(2, 100, &f1), ok);
   CHECK(f1.nCount == SEC_HDR(12, 0, 0) + 100 + 12);
   CHECK(iv_is(&f1, 1));
   CHECK(memcmp(f1.arr + 14, g_data, 100) == 0);            /* sent in clear */

   CHECK_STATUS(process(&f1, NULL), ok);
   CHECK(g_proc_resp.spi == 2);
   CHECK(got_data(100));
}

static void test_authentication_cmac(void)
{
   cmac_config(3);
   CHECK_STATUS(configure(), ok);

   CHECK_STATUS(apply(3, 100, &f1), ok);
   CHECK(f1.nCount == SEC_HDR(0, 4, 0) + 100 + 8);
   CHECK(f1.arr[2] == 0 && f1.arr[3] == 0 && f1.arr[4] == 0 && f1.arr[5] == 1); /* seq 1 */
   CHECK(memcmp(f1.arr + 6, g_data, 100) == 0);             /* sent in clear */

   CHECK_STATUS(process(&f1, NULL), ok);
   CHECK(g_proc_resp.spi == 3);
   CHECK(got_data(100));

   /* The full 16-octet tag can be sent as well. */
   sa_config(4, SDLS_Mode_authentication, SDLS_Auth_Algorithm_cmac, 0, 4, 0, 16, 64);
   CHECK_STATUS(configure(), ok);
   CHECK_STATUS(apply(4, 100, &f2), ok);
   CHECK(f2.nCount == SEC_HDR(0, 4, 0) + 100 + 16);
   CHECK_STATUS(process(&f2, NULL), ok);
   CHECK(got_data(100));
}

static void test_encryption_only(void)
{
   enc_config(5);
   CHECK_STATUS(configure(), ok);

   CHECK_STATUS(apply(5, 64, &f1), ok);
   CHECK(f1.nCount == SEC_HDR(12, 0, 0) + 64);              /* no trailer */
   CHECK(iv_is(&f1, 1));
   CHECK(memcmp(f1.arr + 14, g_data, 64) != 0);             /* encrypted */
   CHECK_STATUS(process(&f1, NULL), ok);
   CHECK(got_data(64));

   /* No integrity: a modified ciphertext is accepted and decrypts to
    * modified plaintext. */
   CHECK_STATUS(apply(5, 64, &f2), ok);
   t = f2;
   t.arr[14 + 10] ^= 0x01;
   CHECK_STATUS(process(&t, NULL), ok);
   CHECK(g_proc_resp.data.nCount == 64);
   CHECK(g_proc_resp.data.arr[10] == (g_data[10] ^ 0x01));
}

/* Every modification of an authenticated frame is rejected, and a rejected
 * frame neither returns data nor advances the anti-replay window. */
static void check_tamper_rejected(asn1SccSDLS_SPI spi, int sec_hdr_len)
{
   CHECK_STATUS(apply(spi, 32, &f1), ok);

   t = f1;                                       /* data field */
   t.arr[sec_hdr_len + 5] ^= 0x01;
   CHECK_STATUS(process(&t, NULL), authentication_failed);
   CHECK(g_proc_resp.data.nCount == 0);

   t = f1;                                       /* MAC */
   t.arr[t.nCount - 1] ^= 0x80;
   CHECK_STATUS(process(&t, NULL), authentication_failed);

   t = f1;                                       /* last octet of the security header */
   t.arr[sec_hdr_len - 1] ^= 0x01;
   CHECK_STATUS(process(&t, NULL), authentication_failed);

   t = f1;                                       /* truncated MAC */
   t.nCount -= 1;
   CHECK_STATUS(process(&t, NULL), authentication_failed);

   g_hdr[3] ^= 0x01;                             /* transfer frame header */
   CHECK_STATUS(process(&f1, NULL), authentication_failed);
   g_hdr[3] ^= 0x01;

   CHECK_STATUS(process(&f1, NULL), ok);         /* the genuine frame is still fresh */
   CHECK(got_data(32));
}

static void test_tamper_detected(void)
{
   ae_config(6);
   CHECK_STATUS(configure(), ok);
   check_tamper_rejected(6, SEC_HDR(12, 0, 0));

   gmac_config(7);
   CHECK_STATUS(configure(), ok);
   check_tamper_rejected(7, SEC_HDR(12, 0, 0));

   cmac_config(8);
   CHECK_STATUS(configure(), ok);
   check_tamper_rejected(8, SEC_HDR(0, 4, 0));
}

static void test_wrong_key(void)
{
   /* Sender and receiver disagree on the key of SPI 9. */
   ae_config(9);
   CHECK_STATUS(configure(), ok);
   CHECK_STATUS(apply(9, 32, &f1), ok);
   CHECK_STATUS(remove_sa(9), ok);
   ae_config(9);
   g_cfg.key.arr[0] ^= 0x01;
   CHECK_STATUS(configure(), ok);
   CHECK_STATUS(process(&f1, NULL), authentication_failed);
}

static void test_anti_replay(void)
{
   /* IV used as the anti-replay counter, window 2. */
   sa_config(10, SDLS_Mode_authenticated_encryption, SDLS_Auth_Algorithm_gmac, 12, 0, 0, 16, 2);
   CHECK_STATUS(configure(), ok);
   CHECK_STATUS(apply(10, 16, &f1), ok);
   CHECK_STATUS(apply(10, 16, &f2), ok);
   CHECK_STATUS(apply(10, 16, &f3), ok);
   CHECK_STATUS(apply(10, 16, &f4), ok);

   CHECK_STATUS(process(&f1, NULL), ok);
   CHECK_STATUS(process(&f1, NULL), replay_detected);       /* same frame again */
   CHECK(g_proc_resp.data.nCount == 0);
   CHECK_STATUS(process(&f4, NULL), replay_detected);       /* 3 ahead > window 2 */
   CHECK_STATUS(process(&f3, NULL), ok);                    /* 2 ahead */
   CHECK_STATUS(process(&f2, NULL), replay_detected);       /* older than f3 */
   CHECK_STATUS(process(&f4, NULL), ok);

   /* Explicit sequence number as the counter (CMAC). */
   cmac_config(11);
   CHECK_STATUS(configure(), ok);
   CHECK_STATUS(apply(11, 16, &f1), ok);
   CHECK_STATUS(process(&f1, NULL), ok);
   CHECK_STATUS(process(&f1, NULL), replay_detected);

   /* Window 0 disables anti-replay. */
   sa_config(12, SDLS_Mode_authenticated_encryption, SDLS_Auth_Algorithm_gmac, 12, 0, 0, 16, 0);
   CHECK_STATUS(configure(), ok);
   CHECK_STATUS(apply(12, 16, &f1), ok);
   CHECK_STATUS(process(&f1, NULL), ok);
   CHECK_STATUS(process(&f1, NULL), ok);
}

static void test_auth_mask(void)
{
   /* Mask over frame header (5) + security header (14), excluding frame
    * header octet 2 (e.g. a frame counter rewritten in transit). */
   sa_config(20, SDLS_Mode_authenticated_encryption, SDLS_Auth_Algorithm_gmac, 12, 0, 0, 16, 0);
   g_cfg.auth_mask.nCount = 5 + SEC_HDR(12, 0, 0);
   memset(g_cfg.auth_mask.arr, 0xFF, (size_t)g_cfg.auth_mask.nCount);
   g_cfg.auth_mask.arr[2] = 0x00;
   CHECK_STATUS(configure(), ok);

   CHECK_STATUS(apply(20, 32, &f1), ok);
   g_hdr[2] ^= 0xFF;                                        /* masked out */
   CHECK_STATUS(process(&f1, NULL), ok);
   CHECK(got_data(32));
   g_hdr[2] ^= 0xFF;
   g_hdr[0] ^= 0x01;                                        /* authenticated */
   CHECK_STATUS(process(&f1, NULL), authentication_failed);
   g_hdr[0] ^= 0x01;

   /* A mask shorter than frame header + security header is refused. */
   sa_config(21, SDLS_Mode_authenticated_encryption, SDLS_Auth_Algorithm_gmac, 12, 0, 0, 16, 0);
   g_cfg.auth_mask.nCount = 4;
   memset(g_cfg.auth_mask.arr, 0xFF, 4);
   CHECK_STATUS(configure(), ok);
   CHECK_STATUS(apply(21, 32, NULL), mask_too_short);
}

static void test_channel_binding(void)
{
   const asn1SccSDLS_Channel_Id vc1 = channel(1, -1);
   const asn1SccSDLS_Channel_Id vc5 = channel(5, -1);
   const asn1SccSDLS_Channel_Id vc2 = channel(2, -1);
   const asn1SccSDLS_Channel_Id vc2_map3 = channel(2, 3);

   /* Bound to VC 1 and to MAP 3 of VC 2; window 0 so f1 can be reused. */
   sa_config(30, SDLS_Mode_authenticated_encryption, SDLS_Auth_Algorithm_gmac, 12, 0, 0, 16, 0);
   g_cfg.channels.nCount = 2;
   g_cfg.channels.arr[0] = vc1;
   g_cfg.channels.arr[1] = vc2_map3;
   CHECK_STATUS(configure(), ok);
   CHECK_STATUS(apply(30, 16, &f1), ok);

   CHECK_STATUS(process(&f1, &vc1), ok);
   CHECK_STATUS(process(&f1, &vc2_map3), ok);
   CHECK_STATUS(process(&f1, NULL), ok);                    /* no channel given */
   CHECK_STATUS(process(&f1, &vc5), sa_channel_mismatch);
   CHECK_STATUS(process(&f1, &vc2), sa_channel_mismatch);   /* VC 2 without MAP */
   CHECK(g_proc_resp.data.nCount == 0);

   /* An SA without binding serves any channel. */
   sa_config(31, SDLS_Mode_authenticated_encryption, SDLS_Auth_Algorithm_gmac, 12, 0, 0, 16, 0);
   CHECK_STATUS(configure(), ok);
   CHECK_STATUS(apply(31, 16, &f2), ok);
   CHECK_STATUS(process(&f2, &vc5), ok);
}

static void test_iv_counter_restore(void)
{
   /* Restart from a checkpoint: last IV sent was 0x0100. */
   ae_config(40);
   g_cfg.exist.last_sent_iv = 1;
   g_cfg.last_sent_iv.nCount = 12;
   g_cfg.last_sent_iv.arr[10] = 0x01;
   CHECK_STATUS(configure(), ok);
   CHECK_STATUS(apply(40, 16, &f1), ok);
   CHECK(iv_is(&f1, 0x0101));

   /* Counter at its maximum: no IV left for this key. */
   ae_config(41);
   g_cfg.exist.last_sent_iv = 1;
   g_cfg.last_sent_iv.nCount = 12;
   memset(g_cfg.last_sent_iv.arr, 0xFF, 12);
   CHECK_STATUS(configure(), ok);
   CHECK_STATUS(apply(41, 16, NULL), iv_exhausted);

   /* The restored value must have the SA's IV width; the failed SA does
    * not take a slot. */
   ae_config(42);
   g_cfg.exist.last_sent_iv = 1;
   g_cfg.last_sent_iv.nCount = 8;
   CHECK_STATUS(configure(), invalid_iv_counter);
   ae_config(42);
   CHECK_STATUS(configure(), ok);
}

static void test_sa_management(void)
{
   ae_config(50);
   CHECK_STATUS(configure(), ok);
   CHECK_STATUS(apply(50, 16, &f1), ok);

   gmac_config(50);
   CHECK_STATUS(configure(), spi_already_in_use);

   CHECK_STATUS(remove_sa(50), ok);
   CHECK_STATUS(remove_sa(50), unknown_spi);
   CHECK_STATUS(apply(50, 16, NULL), unknown_spi);
   CHECK_STATUS(process(&f1, NULL), unknown_spi);
   CHECK(g_proc_resp.spi == 50);

   /* The SPI can be reused (re-keyed) after removal. */
   gmac_config(50);
   CHECK_STATUS(configure(), ok);
   CHECK_STATUS(apply(50, 16, &f2), ok);
   CHECK_STATUS(process(&f2, NULL), ok);
   CHECK_STATUS(remove_sa(50), ok);

   /* The table holds 16 SAs. */
   for (asn1SccSDLS_SPI spi = 100; spi < 116; spi++) {
      ae_config(spi);
      CHECK_STATUS(configure(), ok);
   }
   ae_config(116);
   CHECK_STATUS(configure(), sa_table_full);
   CHECK_STATUS(remove_sa(107), ok);
   CHECK_STATUS(configure(), ok);                           /* SPI 116 fits now */
   CHECK_STATUS(apply(116, 16, &f3), ok);
   CHECK_STATUS(process(&f3, NULL), ok);
}

static void test_invalid_config(void)
{
   sa_config(60, SDLS_Mode_authenticated_encryption, SDLS_Auth_Algorithm_gmac, 12, 0, 0, 0, 0);
   CHECK_STATUS(configure(), invalid_field_lengths);        /* AE without MAC */
   sa_config(60, SDLS_Mode_authenticated_encryption, SDLS_Auth_Algorithm_gmac, 16, 0, 0, 16, 0);
   CHECK_STATUS(configure(), invalid_field_lengths);        /* GCM IV != 12 */
   sa_config(60, SDLS_Mode_authentication, SDLS_Auth_Algorithm_gmac, 12, 0, 0, 8, 0);
   CHECK_STATUS(configure(), invalid_field_lengths);        /* GMAC MAC < 12 */
   sa_config(60, SDLS_Mode_authentication, SDLS_Auth_Algorithm_cmac, 12, 0, 0, 8, 0);
   CHECK_STATUS(configure(), invalid_field_lengths);        /* CMAC with IV */
   sa_config(60, SDLS_Mode_authentication, SDLS_Auth_Algorithm_cmac, 0, 0, 0, 0, 0);
   CHECK_STATUS(configure(), invalid_field_lengths);        /* CMAC without MAC */
   sa_config(60, SDLS_Mode_encryption, SDLS_Auth_Algorithm_gmac, 12, 0, 0, 16, 0);
   CHECK_STATUS(configure(), invalid_field_lengths);        /* encryption with MAC */
   sa_config(60, SDLS_Mode_encryption, SDLS_Auth_Algorithm_gmac, 0, 0, 0, 0, 0);
   CHECK_STATUS(configure(), invalid_field_lengths);        /* encryption without IV */
   sa_config(60, SDLS_Mode_authentication, SDLS_Auth_Algorithm_cmac, 0, 0, 0, 8, 10);
   CHECK_STATUS(configure(), no_anti_replay_counter);       /* window, no counter */

   /* None of the refused SAs was stored. */
   CHECK_STATUS(remove_sa(60), unknown_spi);
   ae_config(60);
   CHECK_STATUS(configure(), ok);
}

static void test_malformed_frames(void)
{
   /* Unknown SPI, on both sides. */
   CHECK_STATUS(apply(999, 16, NULL), unknown_spi);
   CHECK(g_apply_resp.protected_data.nCount == 0);
   t.nCount = 20;
   memset(t.arr, 0, 20);
   t.arr[0] = 0x03;
   t.arr[1] = 0xE7;                                         /* SPI 999 */
   CHECK_STATUS(process(&t, NULL), unknown_spi);
   CHECK(g_proc_resp.spi == 999);

   /* Too short for an SPI. */
   t.nCount = 1;
   CHECK_STATUS(process(&t, NULL), data_too_short);
   CHECK(g_proc_resp.spi == 0);

   /* Shorter than security header + MAC. */
   ae_config(70);
   CHECK_STATUS(configure(), ok);
   CHECK_STATUS(apply(70, 16, &f1), ok);
   t = f1;
   t.nCount = SEC_HDR(12, 0, 0) + 15;
   CHECK_STATUS(process(&t, NULL), data_too_short);
   t.nCount = 10;
   CHECK_STATUS(process(&t, NULL), data_too_short);
}

static void test_size_limits(void)
{
   /* Largest frame header and data field. */
   g_hdr_len = sizeof(g_hdr);

   ae_config(80);
   CHECK_STATUS(configure(), ok);
   CHECK_STATUS(apply(80, sizeof(g_data), &f1), ok);
   CHECK(f1.nCount == SEC_HDR(12, 0, 0) + (int)sizeof(g_data) + 16);
   CHECK_STATUS(process(&f1, NULL), ok);
   CHECK(got_data(sizeof(g_data)));

   cmac_config(81);
   CHECK_STATUS(configure(), ok);
   CHECK_STATUS(apply(81, sizeof(g_data), &f2), ok);
   CHECK_STATUS(process(&f2, NULL), ok);
   CHECK(got_data(sizeof(g_data)));

   /* Every security header field present: IV 12, seq 8 (the anti-replay
    * counter then), pad length 4. */
   sa_config(82, SDLS_Mode_authenticated_encryption, SDLS_Auth_Algorithm_gmac, 12, 8, 4, 16, 64);
   CHECK_STATUS(configure(), ok);
   CHECK_STATUS(apply(82, sizeof(g_data), &f3), ok);
   CHECK(f3.nCount == SEC_HDR(12, 8, 4) + (int)sizeof(g_data) + 16);
   CHECK_STATUS(process(&f3, NULL), ok);
   CHECK(got_data(sizeof(g_data)));
}

static void test_empty_data(void)
{
   ae_config(90);
   CHECK_STATUS(configure(), ok);
   CHECK_STATUS(apply(90, 0, &f1), ok);
   CHECK(f1.nCount == SEC_HDR(12, 0, 0) + 16);
   CHECK_STATUS(process(&f1, NULL), ok);
   CHECK(got_data(0));

   cmac_config(91);
   CHECK_STATUS(configure(), ok);
   CHECK_STATUS(apply(91, 0, &f2), ok);
   CHECK(f2.nCount == SEC_HDR(0, 4, 0) + 8);
   CHECK_STATUS(process(&f2, NULL), ok);
   CHECK(got_data(0));

   /* No frame header at all. */
   g_hdr_len = 0;
   CHECK_STATUS(apply(90, 8, &f3), ok);
   CHECK_STATUS(process(&f3, NULL), ok);
   CHECK(got_data(8));
}

static void test_pad_length(void)
{
   /* Encryption only, so the Pad Length octet can be edited without
    * breaking a MAC. Window 0 so f1 can be reused. */
   sa_config(95, SDLS_Mode_encryption, SDLS_Auth_Algorithm_gmac, 12, 0, 1, 0, 0);
   CHECK_STATUS(configure(), ok);
   CHECK_STATUS(apply(95, 16, &f1), ok);
   CHECK(f1.nCount == SEC_HDR(12, 0, 1) + 16);
   CHECK(f1.arr[14] == 0);                                  /* sent as zero */
   CHECK_STATUS(process(&f1, NULL), ok);
   CHECK(got_data(16));

   t = f1;
   t.arr[14] = 4;                                           /* 4 fill octets */
   CHECK_STATUS(process(&t, NULL), ok);
   CHECK(got_data(12));

   t.arr[14] = 17;                                          /* more than the data */
   CHECK_STATUS(process(&t, NULL), invalid_pad_length);
}

static void test_crypto_failure(void)
{
   ae_config(97);
   CHECK_STATUS(configure(), ok);
   cmac_config(98);
   CHECK_STATUS(configure(), ok);
   CHECK_STATUS(apply(97, 16, &f1), ok);
   CHECK_STATUS(apply(98, 16, &f2), ok);

   set_aes_status(Crypto_Status_failed);
   CHECK_STATUS(apply(97, 16, NULL), crypto_backend_failed);
   CHECK(g_apply_resp.protected_data.nCount == 0);
   CHECK_STATUS(process(&f1, NULL), crypto_backend_failed);
   CHECK(g_proc_resp.data.nCount == 0);
   CHECK_STATUS(process(&f2, NULL), ok);                    /* CMAC needs no AES block */
   set_aes_status(Crypto_Status_ok);
   CHECK_STATUS(process(&f1, NULL), ok);                    /* window not advanced */
   CHECK(got_data(16));

   CHECK_STATUS(apply(98, 16, &f3), ok);
   set_cmac_status(Crypto_Status_failed);
   CHECK_STATUS(apply(98, 16, NULL), crypto_backend_failed);
   CHECK_STATUS(process(&f3, NULL), crypto_backend_failed);
   set_cmac_status(Crypto_Status_ok);
   CHECK_STATUS(process(&f3, NULL), ok);
}

/* ---------------------------------------------------------------------- */
/* Runner                                                                 */
/* ---------------------------------------------------------------------- */

static const struct {
   const char *name;
   void (*run)(void);
} k_tests[] = {
   { "authenticated_encryption", test_authenticated_encryption },
   { "authentication_gmac",      test_authentication_gmac },
   { "authentication_cmac",      test_authentication_cmac },
   { "encryption_only",          test_encryption_only },
   { "tamper_detected",          test_tamper_detected },
   { "wrong_key",                test_wrong_key },
   { "anti_replay",              test_anti_replay },
   { "auth_mask",                test_auth_mask },
   { "channel_binding",          test_channel_binding },
   { "iv_counter_restore",       test_iv_counter_restore },
   { "sa_management",            test_sa_management },
   { "invalid_config",           test_invalid_config },
   { "malformed_frames",         test_malformed_frames },
   { "size_limits",              test_size_limits },
   { "empty_data",               test_empty_data },
   { "pad_length",               test_pad_length },
   { "crypto_failure",           test_crypto_failure },
};
#define TEST_COUNT (sizeof(k_tests) / sizeof(k_tests[0]))

/* Results, to be read with the debugger once test_finished is set. */
volatile test_result_t test_results[TEST_COUNT];
volatile unsigned test_done;       /* tests run so far */
volatile unsigned test_checks;     /* checks run, all tests */
volatile unsigned test_failures;   /* tests with at least one failed check */
volatile int test_finished;

/* Leaves the encryptor with an empty SA table and working crypto, whatever
 * the previous test did (tests use SPIs below 200). */
static void cleanup(void)
{
   set_aes_status(Crypto_Status_ok);
   set_cmac_status(Crypto_Status_ok);
   for (asn1SccSDLS_SPI spi = 1; spi < 200; spi++) {
      (void)remove_sa(spi);
   }
   (void)remove_sa(999);
}

void test_env_startup(void)
{
   for (size_t i = 0; i < sizeof(g_data); i++) {
      g_data[i] = (uint8_t)(i * 7u + 1u);
   }
   test_done = 0;
   test_checks = 0;
   test_failures = 0;
   test_finished = 0;
}

void test_env_PI_run_tests(void)
{
   if (test_finished) {
      return;
   }

   cleanup();
   for (unsigned i = 0; i < TEST_COUNT; i++) {
      g_result = &test_results[i];
      reset_header();
      k_tests[i].run();
      cleanup();
      test_checks += g_result->checks;
      if (g_result->failures != 0) {
         test_failures++;
      }
      test_done = i + 1;
   }
   test_finished = 1;
}
